-- 0003: catalog, staff, customers
create table public.service_categories (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, name text not null, name_bn text, sort_order int not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz);
create index service_categories_biz_idx on public.service_categories(business_id);
create table public.services (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, category_id uuid references public.service_categories(id) on delete set null, name text not null, name_bn text, description text, duration_minutes int not null check (duration_minutes > 0), buffer_minutes int not null default 0 check (buffer_minutes >= 0), price_minor bigint not null default 0 check (price_minor >= 0), currency text not null default 'BDT', is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz);
create index services_biz_idx on public.services(business_id); create index services_biz_active_idx on public.services(business_id, is_active);
create table public.staff_profiles (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, user_id uuid references public.profiles(id) on delete set null, display_name text not null, title text, bio text, avatar_url text, is_active boolean not null default true, is_bookable boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz);
create index staff_profiles_biz_idx on public.staff_profiles(business_id);
create table public.staff_services (staff_id uuid not null references public.staff_profiles(id) on delete cascade, service_id uuid not null references public.services(id) on delete cascade, business_id uuid not null references public.businesses(id) on delete cascade, primary key (staff_id, service_id));
create index staff_services_biz_idx on public.staff_services(business_id);
create table public.staff_hours (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, staff_id uuid not null references public.staff_profiles(id) on delete cascade, day_of_week int not null check (day_of_week between 0 and 6), open_time time, close_time time, is_closed boolean not null default false, unique(staff_id, day_of_week));
create index staff_hours_biz_idx on public.staff_hours(business_id, staff_id);
create table public.staff_breaks (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, staff_id uuid not null references public.staff_profiles(id) on delete cascade, day_of_week int check (day_of_week between 0 and 6), break_date date, start_time time not null, end_time time not null, created_at timestamptz not null default now());
create index staff_breaks_biz_idx on public.staff_breaks(business_id, staff_id);
create table public.staff_leaves (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, staff_id uuid not null references public.staff_profiles(id) on delete cascade, start_date date not null, end_date date not null, reason text, created_at timestamptz not null default now(), check (end_date >= start_date));
create index staff_leaves_biz_idx on public.staff_leaves(business_id, staff_id, start_date, end_date);
create table public.customers (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, user_id uuid references public.profiles(id) on delete set null, full_name text not null, phone text, email text, notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz);
create index customers_biz_idx on public.customers(business_id); create index customers_biz_phone_idx on public.customers(business_id, phone);
create trigger services_updated before update on public.services for each row execute function public.set_updated_at();
create trigger staff_profiles_updated before update on public.staff_profiles for each row execute function public.set_updated_at();
create trigger customers_updated before update on public.customers for each row execute function public.set_updated_at();
